// Some portions generated by Codex
package org.eclipse.rdf4j.queryrender;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertAll;

import java.util.Map;

import org.assertj.core.api.ThrowableAssert.ThrowingCallable;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.BlankNodeReferences;
import org.eclipse.rdf4j.queryrender.sparql.PrefixIndex;
import org.eclipse.rdf4j.queryrender.sparql.util.TermRenderer;
import org.junit.jupiter.api.Test;

class ReservedIriRenderingTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final PrefixIndex NO_PREFIXES = new PrefixIndex(Map.of());
	private static final IRI RESERVED = VF.createIRI("_:identity");

	@Test
	void rejectsReservedIrisAsValuesAndLiteralDatatypes() {
		assertAll(
				() -> assertUnsupportedIdentity(() -> RenderUtils.toSPARQL(RESERVED)),
				() -> assertUnsupportedIdentity(() -> TermRenderer.convertIRIToString(RESERVED, NO_PREFIXES, false)),
				() -> assertUnsupportedIdentity(() -> RenderUtils.toSPARQL(VF.createLiteral("value", RESERVED))),
				() -> assertUnsupportedIdentity(
						() -> TermRenderer.convertValueToString(VF.createLiteral("value", RESERVED),
								NO_PREFIXES, false)));
	}

	@Test
	void rejectsReservedIrisRecursivelyInsideNestedTripleTerms() {
		TripleTerm nested = VF.createTripleTerm(VF.createIRI("urn:inner"), VF.createIRI("urn:p"),
				VF.createTripleTerm(RESERVED, VF.createIRI("urn:q"), VF.createIRI("urn:object")));

		assertAll(
				() -> assertUnsupportedIdentity(() -> RenderUtils.toSPARQL(nested)),
				() -> assertUnsupportedIdentity(() -> TermRenderer.convertValueToString(nested, NO_PREFIXES, false)));
	}

	@Test
	void prefixCompactionDoesNotHideReservedIriIdentityAmbiguity() {
		PrefixIndex index = new PrefixIndex(Map.of("ex", "_:"));
		assertAll(
				() -> assertUnsupportedIdentity(() -> TermRenderer.convertIRIToString(RESERVED, index, true)),
				() -> assertUnsupportedIdentity(
						() -> TermRenderer.convertValueToString(VF.createLiteral("value", RESERVED),
								index, true)));
	}

	@Test
	void ordinaryIrisRemainValuesAndEscapeIriRefDelimiters() {
		IRI ordinary = VF.createIRI("urn:ordinary");
		IRI escaped = VF.createIRI("urn:ordinary value");
		String escapedReference = BlankNodeReferences.toIRIRef(escaped.stringValue());

		assertThat(RenderUtils.toSPARQL(ordinary)).isEqualTo("<urn:ordinary>");
		assertThat(TermRenderer.convertIRIToString(ordinary, NO_PREFIXES, false)).isEqualTo("<urn:ordinary>");
		assertThat(RenderUtils.toSPARQL(escaped)).isEqualTo(escapedReference);
		assertThat(TermRenderer.convertIRIToString(escaped, NO_PREFIXES, false)).isEqualTo(escapedReference);
		assertThat(TermRenderer.convertIRIToString(escaped,
				new PrefixIndex(Map.of("ex", "urn:ordinary ")), true)).isEqualTo(escapedReference);
	}

	private static void assertUnsupportedIdentity(ThrowingCallable render) {
		assertThatThrownBy(render)
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("blank-node identity")
				.hasMessageContaining("IRI");
	}
}
